import os
api_key = open(os.environ.get('GALAXY_API_KEY_FILE', '')).read().strip()
import bioblend.galaxy
gi = bioblend.galaxy.GalaxyInstance(url='https://usegalaxy.org', key=api_key)

history_id = 'bbd44e69cb8906b547772a78169a2d18'

# Try using BioBlend tool submission for PhyKIT evolutionary_rate
tool_id = 'toolshed.g2.bx.psu.edu/repos/goeckslab/phykit_metrics/phykit_metrics/0.2.0+galaxy0'

inputs = {
    'operation': {
        'selector': 'evolutionary_rate',
        'input_mode': {
            'selector': 'single',
            'input': {'src': 'hda', 'id': 'f9cad7b01a4721352f509fa03c0afb86'}
        }
    }
}

result = gi.tools.run_tool(history_id, tool_id, inputs, input_format='21.01')
print(f'Result: {result}')
"

